from pathlib import Path
import hashlib
import json

root = Path('products/distribution/sqlite-community-directory')
files = {
    'operator-submission-packet.md': 'e96a98a22124ba63287c3047da95b0adcc073077d23e52a4d0e368830afbc0b4',
    'director-referral-candidate.diff': '1017529e2e4b4268992686b690268b13d3c4d3ca5d7e98195a853833314360d8',
}
for name, expected in files.items():
    actual = hashlib.sha256((root / name).read_bytes()).hexdigest()
    print(json.dumps({'file': name, 'sha256': actual, 'matches': actual == expected}))
for path in sorted(root.rglob('*')):
    if path.is_file() and any(term in path.name.lower() for term in ('readiness', 'decision', 'review', 'independent')):
        print(json.dumps({'candidate': str(path), 'bytes': path.stat().st_size}))
